      'kmh-about-heading': 'KMH — Leading European Manufacturer of Pipe Systems',
      'kmh-about-body':    'KMH is one of the leading manufacturers in Europe for clamping ring- or flange-connected pipes, components and systems for aspiration and bulk goods of all kinds. Made of black steel and stainless steel. We offer a comprehensive catalogue range with pipes, formed pipe parts and distribution systems in the &ldquo;modular system&rdquo;. We specialise in individual pipe systems and special customized products of all kinds, in order to be able to respond quickly and flexibly to your special requirements. All entirely from our in-house manufacturing &mdash; Made in Germany. We are: fast, innovative and competent in the implementation. For over 35 years. Worldwide. Whether standard range, series or individual production &mdash; we are at the service of our customers.',
