      /* ---------- House Brand cards (index.html) ---------- */
      'hb-badge':   'House Brand',
      'hb-uno-h3':  'UNO Chain',
      'hb-uno-p':   'ISO 9001 certified standard roller chains &mdash; A &amp; B series, single and multi-strand. Cost-efficient with premium performance for general industrial conveying applications.',
      'hb-trio-h3': 'TRIO Chain',
      'hb-trio-p':  'Heavy-duty forged chains engineered for steel mills, cement plants, and animal feed mills. TRIO (P.102 mm) is built for extreme-load conveying and processing applications.',

      /* ---------- FAQ section (index.html) ---------- */
      'faq-eyebrow': 'Frequently Asked Questions',
      'faq-h2':      'Common Questions About Our Chain Solutions',
      'faq-intro':   'Everything you need to know about MPC\'s products, services, and support.',
      'faq-q1': 'What industries does MPC specialise in?',
      'faq-q2': 'What chain brands does MPC distribute?',
      'faq-q3': 'Does MPC provide after-sales support and maintenance?',
      'faq-q4': 'What areas does MPC deliver to?',
      'faq-q5': 'How do I know which chain is right for my application?',
      'faq-q6': 'What chain standards does MPC supply?',
      'faq-q7': 'How long does it take to get a quote?',
      'faq-q8': 'Does MPC supply chains for food-grade applications?',
      'faq-a1': 'MPC specialises in industrial chain solutions for four key sectors: <strong>steel manufacturing</strong>, <strong>cement production</strong>, <strong>palm oil milling</strong>, and <strong>sugar processing</strong>. We also serve escalator maintenance companies, animal feed mills, automotive manufacturing, and general industrial facilities across Thailand and Southeast Asia.',
      'faq-a2': 'MPC is the authorised distributor for several world-class brands:<ul><li><strong>IWIS</strong> (Germany) &mdash; precision engineering chains &amp; systems</li><li><strong>HS Chain</strong> (Korea) &mdash; heavy conveyor &amp; industrial chains</li><li><strong>KMH</strong> (Japan) &mdash; pipe conveyor systems &amp; components</li><li><strong>Dongbo</strong> (Korea) &mdash; ANSI-certified standard roller chains</li></ul>We also offer our proprietary <strong>UNO Chain</strong> (ISO roller chains) and <strong>TRIO Chain</strong> (heavy forged chains) house brands.',
      'faq-a3': 'Yes &mdash; after-sales service is a core part of MPC\'s offering. We provide technical consultation, chain failure analysis, and direct coordination with manufacturers to resolve issues quickly. Unlike pure distributors, we handle warranty claims and technical problems on your behalf, so you don\'t need to deal with overseas manufacturers directly.',
      'faq-a4': 'We deliver across <strong>all of Thailand</strong>, with express logistics from our Bangkok warehouse. We also serve customers throughout Southeast Asia including Myanmar, Laos, Cambodia, Vietnam, and the broader ASEAN region. Contact us for export pricing and lead times.',
      'faq-a5': 'Our technical team selects the right chain based on your application parameters: load capacity, operating speed, temperature range, chemical exposure, and lubrication conditions. Share your existing chain number, equipment model, or operating conditions with us and we\'ll recommend the optimal solution &mdash; free of charge.',
      'faq-a6': 'MPC supplies chains to international standards including ANSI B29.1, ISO 606, DIN 8187/8188, and JIS B1801. Our range covers pitches from 6.35mm (1/4") up to 102mm heavy forged chains, in single, double, and triple strand configurations. We also supply metric and non-standard chains on request.',
      'faq-a7': 'For standard supply items, we typically respond within <strong>one business day</strong>. For custom or imported products, allow 2–3 business days for a detailed quotation including lead time. Contact us by email at contact@motionpluscorp.com or call <a href="tel:+6622865656">02 286-5656</a>.',
      'faq-a8': 'Yes. We supply food-grade compliant chains for palm oil processing, sugar refining, and other food industry applications. These chains use food-safe lubricants, stainless steel pins and plates, and materials that meet hygienic handling requirements. Ask our team for food-grade specification sheets.',

