      'iwis-rl-desc-text':  '<p><strong>โซ่ชั้นเดียวและโซ่สองชั้น</strong></p><p>IWIS ออกแบบช่องว่างระหว่างโรลเลอร์กับบุชให้เหมาะสมกับการหล่อลื่น ลดแรงเสียดทานในการใช้งานรอบสูง โซ่ชั้นเดียวและโซ่สองชั้นระยะพิท 3/8&quot; เหมาะสำหรับโซ่ขับเครื่องยนต์ ลูกสูบ ปั๊มน้ำมัน โซ่ขับยานยนต์ และงานในอุตสาหกรรมขุดเจาะน้ำมัน</p><p>จุดเด่นของ IWIS คือความเชี่ยวชาญด้านโซ่ระยะพิทเล็ก ขนาด 8 มม. ออกแบบเฉพาะสำหรับงานที่ต้องการน้ำหนักเบา แรงเหวี่ยงหนีศูนย์ต่ำ และแรงขับสูง</p>',

