      /* ---------- FAQ section (index.html) ---------- */
      'faq-eyebrow': 'คำถามที่พบบ่อย',
      'faq-h2':      'คำถามที่ลูกค้าถามบ่อยเกี่ยวกับโซ่และบริการของ MPC',
      'faq-intro':   'ทุกสิ่งที่ควรรู้เกี่ยวกับสินค้า บริการ และการสนับสนุนทางเทคนิคของเรา',
      'faq-q1': 'MPC เชี่ยวชาญในอุตสาหกรรมใดบ้าง?',
      'faq-q2': 'MPC จำหน่ายโซ่แบรนด์ใดบ้าง?',
      'faq-q3': 'MPC มีบริการหลังการขายหรือไม่?',
      'faq-q4': 'MPC จัดส่งได้ทั่วประเทศไทยหรือไม่?',
      'faq-q5': 'จะทราบได้อย่างไรว่าโซ่แบบไหนเหมาะกับงานของเรา?',
      'faq-q6': 'MPC จัดหาโซ่ตามมาตรฐานใดบ้าง?',
      'faq-q7': 'รอใบเสนอราคานานแค่ไหน?',
      'faq-q8': 'MPC มีโซ่เกรดอาหารหรือไม่?',
      'faq-a1': 'MPC เชี่ยวชาญโซ่อุตสาหกรรมสำหรับสี่ภาคหลัก: <strong>เหล็กกล้า</strong>, <strong>ปูนซีเมนต์</strong>, <strong>ปาล์มน้ำมัน</strong> และ <strong>น้ำตาล</strong> นอกจากนี้ยังให้บริการงานบำรุงรักษาบันไดเลื่อน โรงอาหารสัตว์ อุตสาหกรรมยานยนต์ และโรงงานทั่วไปทั่วประเทศไทยและเอเชียตะวันออกเฉียงใต้',
      'faq-a2': 'MPC เป็นตัวแทนจำหน่ายอย่างเป็นทางการของหลายแบรนด์ระดับโลก:<ul><li><strong>IWIS</strong> (เยอรมนี) &mdash; โซ่วิศวกรรมความแม่นยำสูง</li><li><strong>HS Chain</strong> (เกาหลี) &mdash; โซ่ลำเลียงหนักและโซ่อุตสาหกรรม</li><li><strong>KMH</strong> (เยอรมนี) &mdash; ระบบสายพานท่อและชิ้นส่วน</li><li><strong>Dongbo</strong> (เกาหลี) &mdash; โซ่ลูกกลิ้งมาตรฐาน ANSI รับรองแล้ว</li></ul>พร้อมแบรนด์ของเราเอง <strong>UNO Chain</strong> (โซ่ลูกกลิ้ง ISO) และ <strong>TRIO Chain</strong> (โซ่เหล็กหล่อสมรรถนะสูง)',
      'faq-a3': 'ใช่ครับ &mdash; บริการหลังการขายเป็นหัวใจหลักของ MPC เราให้คำปรึกษาทางเทคนิค วิเคราะห์ความเสียหายของโซ่ และประสานงานกับผู้ผลิตโดยตรงเพื่อแก้ปัญหาได้เร็ว ต่างจากตัวแทนทั่วไป เราดูแลเรื่องการรับประกันและปัญหาทางเทคนิคแทนคุณ โดยไม่ต้องติดต่อผู้ผลิตต่างประเทศเอง',
      'faq-a4': 'เราจัดส่งทั่ว<strong>ประเทศไทย</strong> จากคลังสินค้ากรุงเทพฯ และยังให้บริการลูกค้าทั่วเอเชียตะวันออกเฉียงใต้ ทั้งเมียนมา ลาว กัมพูชา เวียดนาม และภูมิภาค ASEAN ติดต่อเราสำหรับราคาส่งออกและระยะเวลาจัดส่ง',
      'faq-a5': 'ทีมเทคนิคของเราคัดเลือกโซ่ตามพารามิเตอร์จริงของงาน: โหลดรับน้ำหนัก ความเร็วใช้งาน ช่วงอุณหภูมิ การสัมผัสสารเคมี และสภาพการหล่อลื่น เพียงแจ้งหมายเลขโซ่เดิม รุ่นอุปกรณ์ หรือเงื่อนไขการทำงาน เราจะแนะนำที่เหมาะสมที่สุด &mdash; ไม่มีค่าใช้จ่าย',
      'faq-a6': 'MPC จัดหาโซ่ตามมาตรฐานสากล ได้แก่ ANSI B29.1, ISO 606, DIN 8187/8188 และ JIS B1801 ครอบคลุมพิตช์ตั้งแต่ 6.35 มม. (1/4") ถึงโซ่เหล็กหล่อหนัก 102 มม. ทั้งแบบเส้นเดียว คู่ และสามเส้น รวมถึงโซ่มาตรฐานเมตริกและโซ่พิเศษตามสั่ง',
      'faq-a7': 'สำหรับสินค้ามาตรฐาน เราตอบกลับภายใน<strong>หนึ่งวันทำการ</strong> สำหรับสินค้าพิเศษหรือนำเข้า ใช้เวลา 2–3 วันทำการสำหรับใบเสนอราคาโดยละเอียดรวมถึงระยะเวลานำ ติดต่อทางอีเมล contact@motionpluscorp.com หรือโทร <a href="tel:+6622865656">02 286-5656</a>',
      'faq-a8': 'มีครับ เราจัดหาโซ่เกรดอาหารสำหรับการแปรรูปปาล์มน้ำมัน การกลั่นน้ำตาล และงานอุตสาหกรรมอาหารอื่นๆ โซ่เหล่านี้ใช้สารหล่อลื่นปลอดภัยสำหรับอาหาร หมุดและแผ่นสแตนเลส และวัสดุที่รองรับมาตรฐานสุขอนามัย ขอแผ่นข้อมูลจำเพาะเกรดอาหารได้จากทีมของเรา',

