      'art1-p1':    'ในอุตสาหกรรมหนัก เช่น การแปรรูปน้ำตาล การสีน้ำมันปาล์ม การผลิตปูนซีเมนต์ และการผลิตเหล็กกล้า โซ่กลไกถือเป็นแกนหลักของกระบวนการผลิต เมื่อโซ่ทำงานภายใต้ภาระต่อเนื่อง การหยุดชะงักที่ไม่คาดคิดไม่ได้เพียงแค่ชะลองาน แต่หยุดรายได้ทั้งหมด',
