      'uno-pg-eyebrow': 'Standard-Rollenketten',
      'uno-pg-h1':      'UNO <em>Kette</em>',
      'uno-pg-sub':     'ISO 9001 · DIN · JIS &nbsp;|&nbsp; A-Serie &amp; B-Serie Doppelstrang',
      'uno-pg-overview-h2': 'UNO Kette',
      'uno-pg-desc-sub':    'Präzisionsgefertigte Standard-Rollenketten für anspruchsvolle Industrieanwendungen',
      'uno-pg-desc-text':   '<p>UNO Kette, speziell produziert von hochstandardisierten OEM-Werken in China, wurde für mehrere weltbekannte Markennamen hergestellt, einschließlich Europa, USA, Japan mit Weltstandards wie ISO 9001, DIN, JIS &mdash; bereitgestellt mit Q.A. (Qualitätssicherung) und Q.C. (Qualitätskontrolle).</p><p>Der Prozess beginnt mit selektivem hochwertigen Stahlmaterial, bearbeitet durch Schneiden und Stanzen durch Automatisierungsmaschinen, gefolgt von Wärmebehandlung durch Trennung jedes einzelnen Teils &mdash; Stift, Buchse, Platte und Rolle &mdash; mit unterschiedlicher Härtetiefe für jedes Teil aufgrund unterschiedlicher Funktionsleistung für Langlebigkeit.</p><p>Vorstrecken ist ein Muss, um verdrehte Ketten zu verhindern und die Kettendehnung zu reduzieren sowie die Zugfestigkeit zu erhöhen.</p><p class="pull">UNO Kette ist die perfekte Lösung für jede anspruchsvolle Anwendung in Bezug auf Preis-Leistungs-Verhältnis.</p>',
