      'iwis-rl-desc-text':  '<p>Simplex- und Duplex-Rollenketten mit einem 3/8&quot;-Teilungsabstand werden hauptsächlich in Steuerantrieben, Ölpumpenantrieben und Hilfsaggregaten, insbesondere für Benzinmotoren, eingesetzt.</p><p>Aufgrund seines kleineren Teilungsabstands reduziert eine Rollenkette mit 8 mm Teilung das Gewicht und damit die Fliehkräfte und Aufprallgeschwindigkeit. Sie ist daher ideal für Downsizing auf Steuerantriebe mit mäßigen Lasten.</p>',
