      /* ---------- FAQ ---------- */
      'faq-eyebrow': 'Häufig gestellte Fragen',
      'faq-h2':      'Häufige Fragen zu unseren Kettenlösungen',
      'faq-intro':   'Alles, was Sie über MPCs Produkte, Dienstleistungen und Support wissen müssen.',
      'faq-q1': 'In welchen Branchen ist MPC spezialisiert?',
      'faq-q2': 'Welche Kettenmarken vertreibt MPC?',
      'faq-q3': 'Bietet MPC After-Sales-Support und Wartung?',
      'faq-q4': 'In welche Gebiete liefert MPC?',
      'faq-q5': 'Woher weiß ich, welche Kette für meine Anwendung geeignet ist?',
      'faq-q6': 'Welche Kettenstandards liefert MPC?',
      'faq-q7': 'Wie lange dauert es, ein Angebot zu erhalten?',
      'faq-q8': 'Liefert MPC Ketten für lebensmittelgerechte Anwendungen?',
      'faq-a1': 'MPC ist auf industrielle Kettenlösungen für vier Schlüsselsektoren spezialisiert: <strong>Stahlfertigung</strong>, <strong>Zementproduktion</strong>, <strong>Palmölmühle</strong> und <strong>Zuckerverarbeitung</strong>. Wir bedienen auch Rolltreppenwartungsunternehmen, Tierfuttermühlen und allgemeine Industrieanlagen in Thailand und Südostasien.',
      'faq-a2': 'MPC ist autorisierter Distributor für mehrere weltbekannte Marken:<ul><li><strong>IWIS</strong> (Deutschland) — Präzisionstechnik-Ketten</li><li><strong>HS Chain</strong> (China) — Schwerlast-Förder- und Industrieketten</li><li><strong>KMH</strong> (Deutschland) — Rohrfördersysteme</li><li><strong>Dongbo</strong> (Korea) — ANSI-zertifizierte Standard-Rollenketten</li></ul>Wir bieten auch unsere Eigenmarken <strong>UNO Kette</strong> und <strong>TRIO Kette</strong>.',
      'faq-a3': 'Ja — After-Sales-Service ist ein Kernbestandteil von MPCs Angebot. Wir bieten technische Beratung, Ketten-Fehleranalyse und direkte Koordination mit Herstellern.',
      'faq-a4': 'Wir liefern in ganz <strong>Thailand</strong> und bedienen auch Kunden in Südostasien einschließlich Myanmar, Laos, Kambodscha, Vietnam und der ASEAN-Region.',
      'faq-a5': 'Unser technisches Team wählt die richtige Kette basierend auf Ihren Anwendungsparametern aus: Tragfähigkeit, Betriebsgeschwindigkeit, Temperaturbereich, chemische Exposition und Schmierbedingungen.',
      'faq-a6': 'MPC liefert Ketten nach internationalen Standards einschließlich ANSI B29.1, ISO 606, DIN 8187/8188 und JIS B1801. Unser Sortiment umfasst Teilungen von 6,35 mm (1/4") bis zu 102 mm Schmiedeketten.',
      'faq-a7': 'Für Standardartikel antworten wir typischerweise innerhalb von <strong>einem Werktag</strong>. Für individuelle oder importierte Produkte planen Sie 2–3 Werktage ein.',
      'faq-a8': 'Ja. Wir liefern lebensmittelgerechte Ketten für Palmölverarbeitung, Zuckerraffinierung und andere Lebensmittelindustrieanwendungen.',

